import { Effect } from 'effect'
import { EventBus, generateId } from '@tuix/core'

const bus = new EventBus()

const program = Effect.gen(function* () {
  yield* bus.subscribe('app', (event) =>
    Effect.sync(() => console.log(event.type))
  )
  yield* bus.publish('app', {
    type: 'ready',
    timestamp: new Date(),
    source: 'main',
    id: generateId(),
  })
})

await Effect.runPromise(program)

import { Effect } from 'effect'
import {
  LiveServices,
  TerminalService,
  detectCapabilities,
  selectGraphicsProtocol,
} from '@tuix/platform'

const caps = detectCapabilities({
  env: process.env,
  columns: 80,
  rows: 24,
})
const protocol = selectGraphicsProtocol(caps)

const program = Effect.gen(function* () {
  const term = yield* TerminalService
  yield* term.writeLine(`graphics: ${protocol}`)
})

await Effect.runPromise(program.pipe(Effect.provide(LiveServices)))

import { style, renderStyled, colorize, renderBox, border } from '@tuix/ansi'

const title = colorize('Status', 'bold')
