  content: [title, body],
  padding: 1,
})

console.log(frame)

import { KeyUtils, parseChar, type KeyEvent } from '@tuix/input'

function onKey(event: KeyEvent): void {
  if (KeyUtils.isQuit(event)) {
    process.exit(0)
  }
  if (KeyUtils.matches(event, 'ctrl+s')) {
    console.log('save')
  }
  if (KeyUtils.bindings.confirm.keys.includes(event.key)) {
    console.log('confirm')
  }
}

const event = parseChar('s', true, false, false)
onKey(event)

import { Effect } from 'effect'
import {
  MemoryStorageLayer,
  StorageService,
} from '@tuix/storage'

const program = Effect.gen(function* () {
  const storage = yield* StorageService
  yield* storage.set('session', { user: 'alice' }, { ttl: 3_600_000 })
  const session = yield* storage.get<{ user: string }>('session')
  const keys = yield* storage.keys('session')
  return { session, keys }
})

const result = await Effect.runPromise(
  program.pipe(Effect.provide(MemoryStorageLayer))
)
console.log(result)
